import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.time.Duration;
import org.springframework.http.client.JdkClientHttpRequestFactory;
import org.springframework.web.client.ResourceAccessException;
import org.springframework.web.client.RestClient;

public class TimeoutDemo {
    public static void main(String[] args) throws Exception {
        // A fake email provider that takes 5 seconds to answer.
        HttpServer slow = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        slow.createContext("/v1/messages", exchange -> {
            try { Thread.sleep(5000); } catch (InterruptedException e) { }
            exchange.sendResponseHeaders(200, -1);
            exchange.close();
        });
        slow.start();

        var factory = new JdkClientHttpRequestFactory();
        factory.setReadTimeout(Duration.ofSeconds(2));
        RestClient email = RestClient.builder()
                .baseUrl("http://127.0.0.1:" + slow.getAddress().getPort())
                .requestFactory(factory)
                .build();

        long started = System.nanoTime();
        try {
            email.post().uri("/v1/messages").retrieve().toBodilessEntity();
        } catch (ResourceAccessException e) {
            long ms = (System.nanoTime() - started) / 1_000_000;
            System.out.println(e.getClass().getSimpleName() + " after " + ms + " ms: " + e.getMessage());
        }
        slow.stop(0);
    }
}

import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.resilience.annotation.EnableResilientMethods;
import org.springframework.resilience.annotation.Retryable;
import org.springframework.web.client.HttpServerErrorException;
import org.springframework.http.HttpStatus;

public class RetryDemo {
    static class EmailClient {
        int calls = 0;
        final long started = System.nanoTime();

        @Retryable(includes = HttpServerErrorException.class, maxRetries = 4, delay = 200, multiplier = 2, jitter = 100, maxDelay = 5000)
        public String send(String to) {
            calls++;
            long ms = (System.nanoTime() - started) / 1_000_000;
            if (calls < 4) {
                System.out.println("attempt " + calls + " at " + ms + " ms: 503");
                throw HttpServerErrorException.create(HttpStatus.SERVICE_UNAVAILABLE, "Service Unavailable", null, null, null);
            }
            System.out.println("attempt " + calls + " at " + ms + " ms: sent");
            return "msg_7f3a";
        }
    }

    @Configuration
    @EnableResilientMethods
    static class Config {
        @Bean
        EmailClient emailClient() {
            return new EmailClient();
        }
    }

    public static void main(String[] args) {
        try (var context = new AnnotationConfigApplicationContext(Config.class)) {
            System.out.println("result: " + context.getBean(EmailClient.class).send("ada@roombook.example"));
        }
    }
}

import io.github.resilience4j.circuitbreaker.CallNotPermittedException;
import io.github.resilience4j.circuitbreaker.CircuitBreaker;
import io.github.resilience4j.circuitbreaker.CircuitBreakerConfig;
import java.time.Duration;
import java.util.function.Supplier;

public class BreakerDemo {
    static boolean redisUp = false;

    static String cacheGet() {
        System.out.println("  asking Redis");
        if (!redisUp) throw new IllegalStateException("Unable to connect to localhost:6379");
        return "cached availability";
    }

    public static void main(String[] args) throws Exception {
        CircuitBreaker breaker = CircuitBreaker.of("redis", CircuitBreakerConfig.custom()
                .slidingWindowSize(5)
                .minimumNumberOfCalls(5)
                .failureRateThreshold(50)
                .waitDurationInOpenState(Duration.ofSeconds(1))
                .permittedNumberOfCallsInHalfOpenState(1)
                .build());
        breaker.getEventPublisher().onStateTransition(e ->
                System.out.println("-> " + e.getStateTransition()));

        Supplier<String> cached = CircuitBreaker.decorateSupplier(breaker, BreakerDemo::cacheGet);
        for (int i = 1; i <= 7; i++) {
            String value;
            try {
                value = cached.get();
            } catch (CallNotPermittedException e) {
                value = "miss, ask PostgreSQL (breaker open)";
            } catch (IllegalStateException e) {
                value = "miss, ask PostgreSQL (" + e.getMessage() + ")";
            }
            System.out.println("request " + i + ": " + value);
        }
        redisUp = true;
        Thread.sleep(1100);
        System.out.println("request 8: " + cached.get());
    }
}

