public Reply createOnce(String key, NewBooking b) {
    String hash = sha256(json.writeValueAsString(b));
    return tx.execute(status -> {
        if (!keys.claim(b.userId(), key, hash)) {
            IdempotencyKeys.Saved saved = keys.find(b.userId(), key).orElseThrow();
            if (!saved.requestHash().equals(hash)) {
                throw new UnprocessableException("idempotency-key-reused",
                        "This Idempotency-Key was used with a different request.", null);
            }
            return new Reply(saved.statusCode(), saved.responseBody(), true);
        }
        String body = json.writeValueAsString(BookingView.from(bookings.insert(b)));
        keys.complete(b.userId(), key, HttpStatus.CREATED.value(), body);
        return new Reply(HttpStatus.CREATED.value(), body, false);
    });
}

