import java.util.List;
import java.util.Map;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

@Component
class OutboxRelay {
    record Event(long id, String eventType, String payload) {}

    private final JdbcClient jdbc;
    private final StringRedisTemplate redis;

    OutboxRelay(JdbcClient jdbc, StringRedisTemplate redis) {
        this.jdbc = jdbc;
        this.redis = redis;
    }

    /** Moves committed events from the outbox table to the roombook:events stream. */
    @Scheduled(fixedDelay = 1000)
    @Transactional
    public void relay() {
        List<Event> events = jdbc.sql("""
                SELECT id, event_type, payload::text FROM outbox
                WHERE published_at IS NULL
                ORDER BY id LIMIT 100
                FOR UPDATE SKIP LOCKED""")
                .query(Event.class).list();
        for (Event e : events) {
            redis.opsForStream().add("roombook:events",
                    Map.of("eventId", "evt_" + e.id(), "type", e.eventType(), "payload", e.payload()));
        }
        if (!events.isEmpty()) {
            jdbc.sql("UPDATE outbox SET published_at = now() WHERE id IN (:ids)")
                    .param("ids", events.stream().map(Event::id).toList())
                    .update();
        }
    }
}

import java.nio.charset.StandardCharsets;
import java.time.Instant;

public class SignDemo {
    public static void main(String[] args) {
        String secret = "whsec_9c2f4e1a7b3d";
        long t = 1790845200L; // 2026-10-01T09:00:00Z
        String json = "{\"id\":\"evt_3f2a91c4\",\"type\":\"booking.confirmed\",\"createdAt\":\"2026-10-01T09:00:00Z\",\"data\":{\"id\":1001,\"roomId\":1,\"startsAt\":\"2026-10-05T14:00:00Z\",\"endsAt\":\"2026-10-05T15:30:00Z\"}}";
        byte[] body = json.getBytes(StandardCharsets.UTF_8);
        byte[] changed = json.replace("1001", "1002").getBytes(StandardCharsets.UTF_8);

        String header = WebhookSignature.sign(secret, t, body);
        System.out.println("Roombook-Signature: " + header);
        System.out.println("as sent:       " + WebhookSignature.verify(secret, header, body, Instant.ofEpochSecond(t + 2)));
        System.out.println("body changed:  " + WebhookSignature.verify(secret, header, changed, Instant.ofEpochSecond(t + 2)));
        System.out.println("an hour later: " + WebhookSignature.verify(secret, header, body, Instant.ofEpochSecond(t + 3600)));
    }
}

import java.net.URI;
import java.time.Instant;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.ErrorResponseException;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

@RestController
class EmailEventsController {
    private final JdbcClient jdbc;
    private final JsonMapper json;
    private final String secret;

    EmailEventsController(JdbcClient jdbc, JsonMapper json, @Value("${roombook.email.webhook-secret}") String secret) {
        this.jdbc = jdbc;
        this.json = json;
        this.secret = secret;
    }

    @PostMapping("/v1/hooks/email")
    @Transactional
    public ResponseEntity<Void> receive(@RequestHeader(name = "Roombook-Signature", defaultValue = "") String signature,
                                        @RequestBody byte[] raw) {
        if (!WebhookSignature.verify(secret, signature, raw, Instant.now())) {
            ProblemDetail problem = ProblemDetail.forStatusAndDetail(HttpStatus.UNAUTHORIZED,
                    "The Roombook-Signature header doesn't match the body.");
            problem.setType(URI.create("https://roombook.example/problems/bad-signature"));
            problem.setTitle("Signature check failed");
            throw new ErrorResponseException(HttpStatus.UNAUTHORIZED, problem, null);
        }
        JsonNode event = json.readTree(raw);
        int inserted = jdbc.sql("INSERT INTO processed_events (event_id) VALUES (:id) ON CONFLICT DO NOTHING")
                .param("id", event.get("id").asString())
                .update();
        if (inserted == 1 && event.get("type").asString().equals("email.bounced")) {
            jdbc.sql("UPDATE users SET email_bounced_at = now() WHERE lower(email) = lower(:to)")
                    .param("to", event.get("data").get("to").asString())
                    .update();
        }
        return ResponseEntity.noContent().build();
    }
}
